		{"iD then ID, differing", `"iD": "j-other", "ID": "j-bound"`},
		{"all three variants", `"ID": "a", "Id": "b", "iD": "c"`},
		{"ID and escaped lowercase, same value", `"ID": "j-bound", "` + jsonBackslash + `u0069d": "j-bound"`},
	}
