			dir, _ := seedBoundJobStore(t)
			bad := replaceInJob(t, dir, "j-bound", idLine("j-bound"), tc.frag)
			assertJobIDAmbiguous(t, dir, 1, []string{"j-bound", "j-other", "a", "b", "c"}, bad)
		})
	}
